package com.brasa.restaurant.service;import com.brasa.restaurant.dto.Dtos.*;import com.brasa.restaurant.exception.ApiExceptions;import com.brasa.restaurant.mapper.ApiMapper;import com.brasa.restaurant.repository.Repositories.UsuarioRepository;import com.brasa.restaurant.security.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;@Service public class AuthService{private final UsuarioRepository repo;private final PasswordEncoder encoder;private final JwtService jwt;public AuthService(UsuarioRepository r,PasswordEncoder e,JwtService j){repo=r;encoder=e;jwt=j;}public AuthResponse login(LoginRequest x){var u=repo.findFirstByEmailIgnoreCaseAndAtivoTrue(x.email()).filter(v->encoder.matches(x.senha(),v.getSenhaHash())).orElseThrow(()->new ApiExceptions.Business("E-mail ou senha inválidos"));return new AuthResponse(jwt.generate(u),ApiMapper.user(u));}public UsuarioResponse me(){return ApiMapper.user(repo.findById(SecurityUtils.current().userId()).orElseThrow(()->new ApiExceptions.NotFound("Usuário não encontrado")));}}
